 * Types for Qwen Code CLI transcript tracing integration.
 *
 * Qwen Code (a Gemini CLI fork) records each coding-agent session as a JSONL
 * transcript. Every line is a `ChatRecord` describing one event in the
 * conversation — a user prompt, an assistant turn (which may carry Gemini
 * `functionCall` parts), a tool result, or a system message.
 *
 * The assistant message uses the Gemini content shape: a `role` plus a `parts`
 * array where each part is a text part, a `functionCall` part, or a
 * `functionResponse` part (`GeminiPart`).
 */

/**
 * A text part in a Gemini message. `thought` marks internal reasoning that
 * should not be surfaced as user-facing assistant text.
 */
export interface TextPart {
  text: string;
  thought?: boolean;
}

/**
 * A function-call part: the model requesting a tool invocation.
 */
export interface FunctionCallPart {
  functionCall: {
    id: string;
    name: string;
    args?: Record<string, any>;
  };
}

/**
 * A function-response part: the tool output fed back to the model.
 */
export interface FunctionResponsePart {
  functionResponse: {
    id: string;
    name: string;
    response: any;
  };
}

/**
 * A single part of a Gemini message. Either a text part, a functionCall part,
 * or a functionResponse part.
 */
export type GeminiPart = TextPart | FunctionCallPart | FunctionResponsePart;

/**
 * Structured Gemini message: a role plus an ordered list of parts.
 */
export interface GeminiMessage {
  role: string;
  parts: GeminiPart[];
}

/**
 * Result of a tool call, attached to `tool_result` records.
 */
export interface ToolCallResult {
  callId: string;
  status: string;
  resultDisplay?: any;
}

/**
 * Token accounting for an assistant turn, in Gemini's naming.
 */
export interface UsageMetadata {
  promptTokenCount: number;
  candidatesTokenCount: number;
  totalTokenCount: number;
}

/**
 * A single record (one JSONL line) in a Qwen Code conversation transcript.
 */
export interface ChatRecord {
  uuid: string;
  parentUuid: string | null;
  sessionId: string;
  timestamp: string;
  type: 'user' | 'assistant' | 'system' | 'tool_result';
  message?: GeminiMessage | string;
  toolCallResult?: ToolCallResult;
  usageMetadata?: UsageMetadata;
  model?: string;
}

/**
 * OpenAI chat-format tool call, used on assistant messages.
 */
export interface ToolCall {
  id: string;
  type: 'function';
  function: {
    name: string;
    arguments: string;
  };
}

/**
 * OpenAI chat-completion message used in LLM span inputs. Matches the message
 * structure the MLflow UI Chat view renders.
 */
export interface OpenAIMessage {
  role: 'user' | 'assistant' | 'system' | 'tool';
  content: string | null;
  tool_calls?: ToolCall[];
  tool_call_id?: string;
}
