[metadata] {"type": "create", "filePath": "/workspace/repo/libs/typescript/integrations/qwen-code/src/tracing.ts", "content": "/**
 * MLflow tracing integration for Qwen Code CLI transcripts.
 *
 * `processTranscript` reads a JSONL conversation transcript and reconstructs an
 * MLflow trace from it:
 *
 *   qwen_code_conversation        (AGENT)   — the whole turn
 *     ├─ llm_call                 (LLM)     — one per assistant record
 *     │    └─ tool_<name>         (TOOL)    — one per functionCall part
 *     └─ ...
 *
 * LLM spans use the OpenAI chat-completion request/response shape so the MLflow
 * Chat view renders the conversation, and each span is timed in nanoseconds so
 * the waterfall reflects the real turn duration.
 */

import {
  startSpan,
  flushTraces,
  InMemoryTraceManager,
  SpanStatusCode,
  SpanType,
  SpanAttributeKey,
  TraceMetadataKey,
  TokenUsageKey,
  type LiveSpan,
} from '@mlflow/core';

import type { ChatRecord, OpenAIMessage } from './types.js';
import {
  parseTimestampToNs,
  getMessageText,
  getFunctionCalls,
  buildToolResultMap,
  getToolOutput,
  getTokenUsage,
  readTranscript,
} from './transcript.js';

/**
 * Reconstruct OpenAI chat-format message history from the records preceding
 * `targetIndex`. Used to populate LLM span inputs so the MLflow Chat view shows
 * the full conversation context that led up to each assistant call.
 *
 * - user record            → `{ role: 'user', content }`
 * - assistant (text only)  → `{ role: 'assistant', content }` (thoughts excluded)
 * - assistant (functionCall)→ `{ role: 'assistant', content: null, tool_calls: [...] }`
 * - tool_result            → `{ role: 'tool', tool_call_id, content }`
 * - system (with message)  → `{ role: 'system', content }`
 * - system (no message)    → skipped
 */
export function reconstructMessages(
  records: ChatRecord[],
  targetIndex: number,
): OpenAIMessage[] {
  const messages: OpenAIMessage[] = [];
  for (let i = 0; i < targetIndex; i++) {
    const record = records[i];

    if (record.type === 'user') {
      messages.push({ role: 'user', content: getMessageText(record) });
    } else if (record.type === 'assistant') {
      const functionCalls = getFunctionCalls(record);
      if (functionCalls.length > 0) {
        messages.push({
          role: 'assistant',
          content: null,
          tool_calls: functionCalls.map((call) => ({
            id: call.id,
            type: 'function',
            function: {
              name: call.name,
              arguments: JSON.stringify(call.args ?? {}),
            },
          })),
        });
      } else {
        messages.push({ role: 'assistant', content: getMessageText(record) });
      }
