C;IAE9E,MAAM,QAAQ,GAAG,IAAA,gBAAS,EAAC;QACzB,IAAI,EAAE,QAAQ,IAAI,CAAC,IAAI,EAAE;QACzB,MAAM,EAAE,UAAU;QAClB,QAAQ,EAAE,eAAQ,CAAC,IAAI;QACvB,GAAG,CAAC,OAAO,IAAI,IAAI,CAAC,CAAC,CAAC,EAAE,WAAW,EAAE,OAAO,EAAE,CAAC,CAAC,CAAC,EAAE,CAAC;QACpD,MAAM,EAAE,IAAI,CAAC,IAAI,IAAI,EAAE;QACvB,UAAU,EAAE,EAAE,SAAS,EAAE,IAAI,CAAC,IAAI,EAAE,OAAO,EAAE,IAAI,CAAC,EAAE,EAAE;KACvD,CAAC,CAAC;IAEH,2EAA2E;IAC3E,oEAAoE;IACpE,IAAI,UAAU,EAAE,cAAc,EAAE,MAAM,KAAK,WAAW,EAAE,CAAC;QACvD,QAAQ,CAAC,SAAS,CAAC,qBAAc,CAAC,KAAK,EAAE,yBAAyB,CAAC,CAAC;IACtE,CAAC;IAED,QAAQ,CAAC,GAAG,CAAC;QACX,OAAO,EAAE,EAAE,MAAM,EAAE,UAAU,CAAC,CAAC,CAAC,IAAA,6BAAa,EAAC,UAAU,CAAC,CAAC,CAAC,CAAC,EAAE,EAAE;QAChE,GAAG,CAAC,KAAK,IAAI,IAAI,CAAC,CAAC,CAAC,EAAE,SAAS,EAAE,KAAK,EAAE,CAAC,CAAC,CAAC,EAAE,CAAC;KAC/C,CAAC,CAAC;AACL,CAAC","names":[],"sources":["/workspace/repo/libs/typescript/integrations/qwen-code/src/tracing.ts"],"sourcesContent":["/**\n * MLflow tracing integration for Qwen Code CLI transcripts.\n *\n * `processTranscript` reads a JSONL conversation transcript and reconstructs an\n * MLflow trace from it:\n *\n *   qwen_code_conversation        (AGENT)   — the whole turn\n *     ├─ llm_call                 (LLM)     — one per assistant record\n *     │    └─ tool_<name>         (TOOL)    — one per functionCall part\n *     └─ ...\n *\n * LLM spans use the OpenAI chat-completion request/response shape so the MLflow\n * Chat view renders the conversation, and each span is timed in nanoseconds so\n * the waterfall reflects the real turn duration.\n */\n\nimport {\n  startSpan,\n  flushTraces,\n  InMemoryTraceManager,\n  SpanStatusCode,\n  SpanType,\n  SpanAttributeKey,\n  TraceMetadataKey,\n  TokenUsageKey,\n  type LiveSpan,\n} from '@mlflow/core';\n\nimport type { ChatRecord, OpenAIMessage } from './types.js';\nimport {\n  parseTimestampToNs,\n  getMessageText,\n  getFunctionCalls,\n  buildToolResultMap,\n  getToolOutput,\n  getTokenUsage,\n  readTranscript,\n} from './transcript.js';\n\n/**\n * Reconstruct OpenAI chat-format message history from the records preceding\n * `targetIndex`. Used to populate LLM span inputs so the MLflow Chat view shows\n * the full conversation context that led up to each assistant call.\n *\n * - user record            → `{ role: 'user', content }`\n * - assistant (text only)  → `{ role: 'assistant', content }` (thoughts excluded)\n * - assistant (functionCall)→ `{ role: 'assistant', content: null, tool_calls: [...] }`\n * - tool_result            → `{ role: 'tool', tool_call_id, content }`\n * - system (with message)  → `{ role: 'system', content }`\n * - system (no message)    → skipped\n */\nexport function reconstructMessages(\n  records: ChatRecord[],\n  targetIndex: number,\n): OpenAIMessage[] {\n  const messages: OpenAIMessage[] = [];\n  for (let i = 0; i < targetIndex; i++) {\n    const record = records[i];\n\n    if (record.type === 'user') {\n      messages.push({ role: 'user', content: getMessageText(record) });\n    } else if (record.type === 'assistant') {\n      const functionCalls = getFunctionCalls(record);\n      if (functionCalls.length > 0) {\n        messages.push({\n          role: 'assistant',\n          content: null,\n          tool_calls: functionCalls.map((call) => ({\n            id: call.id,\n            type: 'function',\n            function: {\n              name: call.name,\n              arguments: JSON.stringify(call.args ?? {}),\n            },\n          })),\n        });\n      } else {\n        messages.push({ role: 'assistant', content: getMessageText(record) });\n      }\n    } else if (record.type === 'tool_result') {\n      messages.push({\n        role: 'tool',\n        tool_call_id: record.toolCallResult?.callId ?? '',\n        content: getToolOutput(record),\n      });\n    } else if (record.type === 'system') {\n      // System records without a message are context-free markers — skip them.\n      if (record.message) {\n        messages.push({ role: 'system', content: getMessageText(record) });\n      }\n    }\n  }\n  return messages;\n}\n\n/**\n * Read a Qwen Code JSONL transcript and convert it into an MLflow trace.\n *\n * A null path is a no-op: no spans are created and `flushTraces` is not called.\n * For a valid path, an AGENT root span brackets the turn (first user record →\n * last assistant record), one LLM span is created per assistant record, and one\n * TOOL span per functionCall part within an assistant record.\n */\nexport async function processTranscript(\n  transcriptPath: string | null,\n  sessionId?: string,\n): Promise<void> {\n  if (transcriptPath == null) {\n    return;\n  }\n\n  const records = readTranscript(transcriptPath);\n  const toolResultMap = buildToolResultMap(records);\n\n  const assistantRecords = records.filter((record) => record.type === 'assistant');\n  const firstUserRecord = records.find((record) => record.type === 'user');\n  const lastAssistantRecord =\n    assistantRecords.length > 0 ? assistantRecords[assistantRecords.length - 1] : undefined;\n\n  const userPrompt = firstUserRecord ? getMessageText(firstUserRecord) : '';\n  const finalAssistantText = lastAssistantRecord ? getMessageText(lastAssistantRecord) : '';\n\n  const rootStartNs = firstUserRecord ? parseTimestampToNs(firstUserRecord.timestamp) : null;\n  const rootEndNs = lastAssistantRecord ? parseTimestampToNs(lastAssistantRecord.timestamp) : null;\n\n  const resolvedSessionId = sessionId ?? records[0]?.sessionId ?? '';\n\n  // Root AGENT span. The user prompt is passed as a raw string so MLflow can\n  // auto-generate the request preview and the session view renders it cleanly.\n  const rootSpan = startSpan({\n    name: 'qwen_code_conversation',\n    spanType: SpanType.AGENT,\n    inputs: userPrompt,\n    ...(rootStartNs != null ? { startTimeNs: rootStartNs } : {}),\n  });\n\n  for (let i = 0; i < records.length; i++) {\n    const record = records[i];\n    if (record.type !== 'assistant') {\n      continue;\n    }\n\n    const model = record.model ?? 'unknown';\n    // The LLM span covers generation: from the preceding record (the prompt or\n    // the previous tool result the model was waiting on) to this record.\n    const startNs =\n      i > 0 ? parseTimestampToNs(records[i - 1].timestamp) : parseTimestampToNs(record.timestamp);\n    const endNs = parseTimestampToNs(record.timestamp);\n\n    const llmSpan = startSpan({\n      name: 'llm_call',\n      parent: rootSpan,\n      spanType: SpanType.LLM,\n      ...(startNs != null ? { startTimeNs: startNs } : {}),\n      inputs: { model, messages: reconstructMessages(records, i) },\n      attributes: { model },\n    });\n\n    const usage = getTokenUsage(record.usageMetadata);\n    if (usage) {\n      llmSpan.setAttribute(SpanAttributeKey.TOKEN_USAGE, {\n        [TokenUsageKey.INPUT_TOKENS]: usage.input,\n        [TokenUsageKey.OUTPUT_TOKENS]: usage.output,\n        [TokenUsageKey.TOTAL_TOKENS]: usage.total,\n      });\n    }\n\n    llmSpan.end({\n      outputs: {\n        choices: [{ message: { role: 'assistant', content: getMessageText(record) } }],\n      },\n      ...(endNs != null ? { endTimeNs: endNs } : {}),\n    });\n\n    // One TOOL span per functionCall part in this assistant record.\n    for (const call of getFunctionCalls(record)) {\n      createToolSpan(rootSpan, record, call, toolResultMap);\n    }\n  }\n\n  // Root-level token usage: input reflects the LAST assistant call's prompt\n  // size; output sums the generated tokens across every assistant call.\n  if (assistantRecords.length > 0) {\n    const inputTokens = lastAssistantRecord?.usageMetadata?.promptTokenCount ?? 0;\n    const outputTokens = assistantRecords.reduce(\n      (sum, record) => sum + (record.usageMetadata?.candidatesTokenCount ?? 0),\n      0,\n    );\n    rootSpan.setAttribute(SpanAttributeKey.TOKEN_USAGE, {\n      [TokenUsageKey.INPUT_TOKENS]: inputTokens,\n      [TokenUsageKey.OUTPUT_TOKENS]: outputTokens,\n      [TokenUsageKey.TOTAL_TOKENS]: inputTokens + outputTokens,\n    });\n  }\n\n  // Attach session/user metadata to the trace. We use InMemoryTraceManager\n  // directly because `updateCurrentTrace()` requires an active OTel span\n  // context, which transcript-based tracing doesn't have — spans are created\n  // via `startSpan()` without OTel context propagation.\n  const traceId = rootSpan.traceId;\n  if (traceId) {\n    const traceManager = InMemoryTraceManager.getInstance();\n    const trace = traceManager.getTrace(traceId);\n    if (trace) {\n      trace.info.traceMetadata = {\n        ...trace.info.traceMetadata,\n        [TraceMetadataKey.TRACE_SESSION]: resolvedSessionId,\n        [TraceMetadataKey.TRACE_USER]: process.env.USER ?? '',\n      };\n    }\n  }\n\n  rootSpan.end({\n    outputs: finalAssistantText,\n    ...(rootEndNs != null ? { endTimeNs: rootEndNs } : {}),\n  });\n\n  await flushTraces();\n}\n\n/**\n * Create a TOOL span for a single functionCall, bracketed from the assistant\n * record that emitted it to the matching tool_result record. Successful calls\n * leave the span status untouched; cancelled calls are marked ERROR.\n */\nfunction createToolSpan(\n  parentSpan: LiveSpan,\n  assistantRecord: ChatRecord,\n  call: { id: string; name: string; args?: Record<string, any> },\n  toolResultMap: Map<string, ChatRecord>,\n): void {\n  const toolResult = toolResultMap.get(call.id);\n  const startNs = parseTimestampToNs(assistantRecord.timestamp);\n  const endNs = toolResult ? parseTimestampToNs(toolResult.timestamp) : startNs;\n\n  const toolSpan = startSpan({\n    name: `tool_${call.name}`,\n    parent: parentSpan,\n    spanType: SpanType.TOOL,\n    ...(startNs != null ? { startTimeNs: startNs } : {}),\n    inputs: call.args ?? {},\n    attributes: { tool_name: call.name, tool_id: call.id },\n  });\n\n  // Reflect a cancelled tool call in the span status so it stands out in the\n  // trace UI. Successful calls are left in the default (unset) state.\n  if (toolResult?.toolCallResult?.status === 'cancelled') {\n    toolSpan.setStatus(SpanStatusCode.ERROR, 'Tool call was cancelled');\n  }\n\n  toolSpan.end({\n    outputs: { result: toolResult ? getToolOutput(toolResult) : '' },\n    ...(endNs != null ? { endTimeNs: endNs } : {}),\n  });\n}\n"],"version":3}
